-- Execute after stop_delivery_batch_mark.sql, in the same BEGIN IMMEDIATE transaction.
UPDATE runtime_operations SET status=CASE WHEN EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND status='unknown') THEN 'delivery_unknown' WHEN delivered_artifact_count>0 THEN 'delivery_partial' WHEN cancel_requested=1 OR ?5='cancel' THEN 'cancelled' WHEN ?5='denied' THEN 'failed' WHEN attempt<max_attempts THEN 'queued' ELSE 'failed' END,available_at=CASE WHEN delivered_artifact_count=0 AND cancel_requested=0 AND ?5='shutdown' AND attempt<max_attempts THEN CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(retry_delay_secs*1000000) ELSE available_at END,worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,progress_percent=NULL,progress_stage=NULL,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status='delivering' AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER);